package org.deeptimeline.app
import android.app.Dialog
import android.os.Handler
import android.os.Looper
import android.text.Editable
import android.text.TextWatcher
import android.view.WindowManager
import android.widget.EditText
import android.widget.ScrollView
import android.widget.TextView
import java.math.BigDecimal
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.ZoneOffset
class EventEditor(private val activity:MainActivity,private val existing:TimelineEvent?){private val dialog=Dialog(activity);private var mode=existing?.mode?:"LOCAL";private val name=activity.field(existing?.title?:"","Event name");private val initial=existing?.civil?:TimeMath.formatCivil(LocalDateTime.now());private val date=activity.field(initial.substringBefore('T'),"YYYY-MM-DD or -YYYY-MM-DD BCE");private val time=activity.field(initial.substringAfter('T',"12:00:00"),"HH:MM:SS[.nnnnnnnnn]");private val coords=activity.field(existing?.coords?:"","Latitude, Longitude");private val zoneText=activity.label("",14f);private var limitUnit=existing?.maxScaleUnit?:"DAY";private val limitAmount=activity.field(existing?.maxScaleAmount?:"","1/3, 2^10, 1.5e-4; empty = always");private val limitUnitButton=activity.action(""){};private var approvedScaleAmount="";private var approvedScaleUnit="DAY";private val modeButton=activity.action(""){};private val zoneRow=activity.row();private val locationRow=activity.row();private val status=activity.label("",12f);private val saveButton=activity.action("SAVE"){save()};private val handler=Handler(Looper.getMainLooper());private var lookupPending:Runnable?=null;private var lookupSerial=0;private var resolvedFor=existing?.coords?:"";private var frozenZone=existing?.zone?.takeIf{it.isNotBlank()}?:ZoneId.systemDefault().id;private var manualOverride=false;private var saving=false;init{val content=activity.column();content.setPadding(activity.dp(10),activity.dp(4),activity.dp(10),activity.dp(8));val header=activity.row();header.add(activity.label(if(existing==null)"ADD EVENT" else "EDIT EVENT",20f),0,-2,1f);val trash=Glyph(activity,"trash");trash.contentDescription=if(existing==null)"Cancel creation" else "Delete event";header.add(trash,activity.dp(52),activity.dp(52));trash.setOnClickListener{if(existing==null)dialog.dismiss() else activity.confirm("DELETE EVENT","Delete ${existing.title}?"){activity.delete(existing);dialog.dismiss()}};content.add(header);content.add(activity.label("Name"));content.add(name);content.add(activity.label("Date"));content.add(date);content.add(activity.label("Negative years are BCE: -44 = 44 BCE, -12000 = 12000 BCE. No year zero.",12f));content.add(activity.label("Time"));content.add(time);content.add(activity.label("Time interpretation"));modeButton.setOnClickListener{activity.choose("TIME INTERPRETATION",listOf("Local civil time","UTC","Longitude-derived mean solar time")){i->mode=when(i){1->"UTC";2->"LONGITUDINAL";else->"LOCAL"};manualOverride=false;lookupSerial++;updateMode();if(mode=="LOCAL")scheduleLookup()}};content.add(modeButton,-1,activity.dp(46));locationRow.add(coords,0,activity.dp(46),1f);val gps=Glyph(activity,"gps");gps.contentDescription="Get coordinates from GPS";locationRow.add(gps,activity.dp(52),activity.dp(52));gps.setOnClickListener{activity.acquireLocation{lat,lon,extra->coords.setText("$lat, $lon");status.text=extra}};content.add(activity.label("Coordinates (optional for Local)"));content.add(locationRow);zoneRow.add(activity.label("Geographic time zone",13f),0,-2,1f);zoneText.background=activity.border();zoneText.setOnClickListener{pickZone()};zoneRow.add(zoneText,0,activity.dp(46),1f);content.add(zoneRow);content.add(status);content.add(activity.label("Hide event when zoomed out beyond:",14f));content.add(limitAmount,-1,activity.dp(46));limitUnitButton.setOnClickListener{activity.choose("VISIBILITY THRESHOLD UNITS",listOf("DAYS","MEAN SYNODIC MONTHS","MEAN DECEMBER-SOLSTICE YEARS")){limitUnit=listOf("DAY","MONTH","YEAR")[it];updateLimitUnit()}};content.add(limitUnitButton,-1,activity.dp(45));content.add(activity.label("Exact positive rational expressions: 1/3, 2^10, 1.5e-4, 2^10/3. Fractions remain exact, even for repeating decimals. Empty means always visible.",12f));content.add(saveButton,-1,activity.dp(50));coords.addTextChangedListener(object:TextWatcher{override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int){};override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){if(mode=="LOCAL"){manualOverride=false;frozenZone="";resolvedFor="";scheduleLookup()}};override fun afterTextChanged(s:Editable?){}});val scroll=ScrollView(activity).apply{setBackgroundColor(BLACK);setFillViewport(false);addView(content)};dialog.setContentView(scroll);dialog.window?.setBackgroundDrawableResource(android.R.color.black);dialog.window?.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);updateMode();updateLimitUnit();if(mode=="LOCAL"&&coords.text.isNotBlank()&&existing==null)scheduleLookup()};fun show(){dialog.show();dialog.window?.setLayout((activity.resources.displayMetrics.widthPixels*0.96).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)};private fun updateLimitUnit(){limitUnitButton.text=when(limitUnit){"MONTH"->"MEAN SYNODIC MONTHS";"YEAR"->"MEAN SOLSTICE YEARS";else->"DAYS"}};private fun updateMode(){modeButton.text=mode;locationRow.visibility=if(mode=="UTC")android.view.View.GONE else android.view.View.VISIBLE;zoneRow.visibility=if(mode=="LOCAL")android.view.View.VISIBLE else android.view.View.GONE;status.text=when(mode){"LONGITUDINAL"->"UTC offset = longitude × 240 seconds (east positive)";"LOCAL"->if(coords.text.isBlank())"Android device timezone; no coordinates required" else "Offline geographic timezone lookup";else->"UTC offset 00:00"};if(mode=="LOCAL"){if(coords.text.isBlank()){frozenZone=if(existing?.mode=="LOCAL"&&existing.coords.isBlank()&&existing.zone.isNotBlank())existing.zone else ZoneId.systemDefault().id;resolvedFor="";zoneText.text="${if(existing?.mode=="LOCAL"&&existing.coords.isBlank())"SAVED" else "DEVICE"} · $frozenZone"}else if(frozenZone.isNotBlank()&&existing?.coords==coords.text.toString()){resolvedFor=coords.text.toString().trim();zoneText.text=frozenZone}else{zoneText.text="RESOLVING COORDINATES..."}}};private fun scheduleLookup(){lookupPending?.let{handler.removeCallbacks(it)};val snapshot=coords.text.toString().trim();val serial=++lookupSerial;if(mode!="LOCAL")return;if(snapshot.isBlank()){resolvedFor="";frozenZone=if(existing?.mode=="LOCAL"&&existing.coords.isBlank()&&existing.zone.isNotBlank())existing.zone else ZoneId.systemDefault().id;zoneText.text="${if(existing?.mode=="LOCAL"&&existing.coords.isBlank())"SAVED" else "DEVICE"} · $frozenZone";status.text="Android device timezone";return};zoneText.text="RESOLVING COORDINATES...";val pending=Runnable{val position=runCatching{Coordinates.parse(snapshot)}.getOrNull();if(position==null){if(serial==lookupSerial){zoneText.text="ENTER VALID COORDINATES";status.text="Enter latitude, longitude"};return@Runnable};Thread{val result=runCatching{ZoneResolver.resolve(activity,position.first.toDouble(),position.second.toDouble())};activity.runOnUiThread{if(serial!=lookupSerial||mode!="LOCAL"||snapshot!=coords.text.toString().trim())return@runOnUiThread;resolvedFor=snapshot;frozenZone=result.getOrNull()?:"";zoneText.text=frozenZone.ifEmpty{"UNRESOLVED — TAP TO SELECT"};status.text=if(frozenZone.isNotEmpty())"Automatic offline timezone · ${ZoneResolver.SOURCE}" else "No matching zone: tap the timezone field to select manually"}}.start()};lookupPending=pending;handler.postDelayed(pending,350)};private fun pickZone(){val root=activity.column();root.add(activity.label("Optional manual override of the automatic timezone",13f));val query=activity.field("","Search IANA timezone");root.add(query);val results=activity.column();val scroll=ScrollView(activity).apply{addView(results)};root.add(scroll,-1,activity.dp(340));var modal:Dialog?=null;fun fill(q:String){results.removeAllViews();val search=q.trim();val chosen=if(search.isEmpty())listOf(frozenZone,ZoneId.systemDefault().id).filter{it.isNotBlank()}.distinct() else ZoneId.getAvailableZoneIds().filter{it.contains(search,true)}.sorted().take(90);for(zone in chosen)results.add(activity.action(zone){manualOverride=true;lookupSerial++;lookupPending?.let{handler.removeCallbacks(it)};frozenZone=zone;resolvedFor=coords.text.toString().trim();zoneText.text="MANUAL · $zone";status.text="Manual timezone override for the entered coordinates";modal?.dismiss()},-1,activity.dp(44))};query.addTextChangedListener(object:TextWatcher{override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int){};override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){fill(s.toString())};override fun afterTextChanged(s:Editable?){}});fill("");modal=activity.modal("CHOOSE IANA TIMEZONE",root);modal.show();modal.window?.setLayout((activity.resources.displayMetrics.widthPixels*0.94).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)};private fun save(){if(saving)return;try{val title=name.text.toString().trim();val limit=VisibilityScale.normalize(limitAmount.text.toString(),limitUnit);approvedScaleAmount=limit.first;approvedScaleUnit=limit.second;require(title.isNotEmpty()){"Enter an event name"};val civil=TimeMath.parseCivil(date.text.toString(),time.text.toString());val coordValue=if(mode=="UTC")"" else coords.text.toString().trim();val coordinate=if(coordValue.isEmpty())null else Coordinates.parse(coordValue);require(mode!="LONGITUDINAL"||coordinate!=null){"Longitudinal time needs coordinates"};val civilText=TimeMath.formatCivil(civil);if(existing!=null&&existing.civil==civilText&&existing.mode==mode&&existing.coords==coordValue&&(mode!="LOCAL"||existing.zone==frozenZone)){commit(existing.copy(title=title,updated=System.currentTimeMillis(),maxScaleAmount=approvedScaleAmount,maxScaleUnit=approvedScaleUnit));return};when(mode){"UTC"->commitEvent(title,TimeMath.fromUtc(civil),civilText,mode,"","UTC","0");"LONGITUDINAL"->{val (moment,offset)=TimeMath.fromLongitude(civil,coordinate!!.second);commitEvent(title,moment,civilText,mode,coordValue,"",offset)};else->{if(coordinate==null){commitLocal(title,civil,civilText,coordValue,frozenZone.ifBlank{ZoneId.systemDefault().id});return};val snapshot=coordValue;val known=frozenZone.takeIf{it.isNotBlank()&&resolvedFor==snapshot};if(known!=null){commitLocal(title,civil,civilText,snapshot,known);return};saving=true;saveButton.isEnabled=false;status.text="Resolving geographic timezone...";Thread{val result=runCatching{ZoneResolver.resolve(activity,coordinate.first.toDouble(),coordinate.second.toDouble())};activity.runOnUiThread{saving=false;saveButton.isEnabled=true;if(mode!="LOCAL"||snapshot!=coords.text.toString().trim())return@runOnUiThread;val zone=result.getOrNull();if(zone==null){status.text=result.exceptionOrNull()?.message?:"Could not resolve coordinates; tap timezone field to override";zoneText.text="UNRESOLVED — TAP TO SELECT"}else{frozenZone=zone;resolvedFor=snapshot;zoneText.text=zone;runCatching{commitLocal(title,civil,civilText,snapshot,zone)}.onFailure{status.text=it.message?:"Invalid local time"}}}}.start()}}}catch(e:Exception){status.text=e.message?:"Invalid event data"}};private fun commitLocal(title:String,civil:LocalDateTime,civilText:String,coordinate:String,zone:String){val (choices,error)=TimeMath.fromLocal(civil,zone);require(choices.isNotEmpty()){error};fun commitChoice(index:Int){val item=choices[index];commitEvent(title,item.first,civilText,"LOCAL",coordinate,zone,BigDecimal(ZoneOffset.of(item.second).totalSeconds).multiply(BigDecimal("1000000000")).toBigInteger().toString())};if(choices.size==1)commitChoice(0) else activity.choose("AMBIGUOUS LOCAL TIME — CHOOSE UTC OFFSET",choices.map{"${it.second} → ${it.first.utc()}"}){commitChoice(it)}};private fun commitEvent(title:String,moment:Moment,civil:String,mode:String,coords:String,zone:String,offsetNano:String){commit(TimelineEvent(existing?.id?:java.util.UUID.randomUUID().toString(),title,moment,civil,mode,coords,zone,offsetNano,existing?.created?:System.currentTimeMillis(),System.currentTimeMillis(),approvedScaleAmount,approvedScaleUnit))};private fun commit(event:TimelineEvent){activity.save(event);dialog.dismiss();lookupPending?.let{handler.removeCallbacks(it)};lookupSerial++}}
